import requests, concurrent.futures, os
urls=['https://huggingface.co','https://hf.co','https://api.genome.ucsc.edu/getData/sequence?genome=hg38;chrom=chr12;start=7792299;end=7793299','https://raw.githubusercontent.com/kuleshov-group/caduceus/main/README.md','https://pypi.org/simple/torch/']
def get(item):
 u,direct=item
 try:
  s=requests.Session();s.trust_env=not direct
  r=s.get(u,timeout=20)
  print(u,direct,r.status_code,len(r.content),r.text[:100])
  if 'genome' in u and r.ok:open('data/sequence.json','w').write(r.text)
 except Exception as e: print(u,direct,str(e)[:200])
with concurrent.futures.ThreadPoolExecutor() as ex:list(ex.map(get,[(u,d) for u in urls for d in [False,True]]))
PY"
